parameters.jsCode:
const result = $input.first().json;
const context = $('Prepare Async Context').first().json.context;
const processingTime = Date.now() - context.start_time;

let callback;
let parsedSyllabus = null;
let stats = null;

const isSuccess = !result.error && result.choices?.[0]?.message?.content;

if (isSuccess) {
  try {
    const content = result.choices?.[0]?.message?.content || '{}';
    parsedSyllabus = JSON.parse(content);

    // Calculate statistics
    const syllabus = parsedSyllabus.syllabus || parsedSyllabus;
    stats = {
      total_modules: syllabus.modules?.length || 0,
      total_lessons: syllabus.modules?.reduce((sum, m) => sum + (m.lessons?.length || 0), 0) || 0,
      total_hours: syllabus.duration?.total_hours || syllabus.modules?.reduce((sum, m) => sum + (m.duration_hours || 0), 0) || 0
    };

    callback = {
      job_id: context.job_id,
      conversation_id: context.conversation_id,
      user_id: context.user_id,
      guild_id: context.guild_id,
      channel_id: context.channel_id,
      success: true,
      result: {
        ...parsedSyllabus,
        statistics: stats
      },
      metrics: {
        tokens_used: result.usage?.total_tokens || 0,
        prompt_tokens: result.usage?.prompt_tokens || 0,
        completion_tokens: result.usage?.completion_tokens || 0,
        processing_time_ms: processingTime
      },
      meta: {
        provider: 'openai',
        model: result.model || context.model,
        execution_mode: context.execution_mode
      },
      error: null
    };
  } catch (e) {
    callback = {
      job_id: context.job_id,
      conversation_id: context.conversation_id,
      user_id: context.user_id,
      guild_id: context.guild_id,
      channel_id: context.channel_id,
      success: false,
      result: null,
      metrics: {
        tokens_used: result.usage?.total_tokens || 0,
        processing_time_ms: processingTime
      },
      meta: {
        provider: 'openai',
        execution_mode: context.execution_mode
      },
      error: {
        code: 'PARSE_ERROR',
        message: 'Failed to parse syllabus response: ' + e.message,
        retriable: false
      }
    };
  }
} else {
  const errorCode = result.error?.code || 'API_ERROR';
  const errorMessage = result.error?.message || 'OpenAI API error';

  callback = {
    job_id: context.job_id,
    conversation_id: context.conversation_id,
    user_id: context.user_id,
    guild_id: context.guild_id,
    channel_id: context.channel_id,
    success: false,
    result: null,
    metrics: {
      tokens_used: 0,
      processing_time_ms: processingTime
    },
    meta: {
      provider: 'openai',
      execution_mode: context.execution_mode
    },
    error: {
      code: errorCode,
      message: errorMessage,
      retriable: ['rate_limit_exceeded', 'timeout', 'server_error'].includes(errorCode)
    }
  };
}

// RFC-040: Generate HMAC signature
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(callback);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return {
  json: {
    callback: callback,
    callback_url: context.callback_url,
    signature: signature,
    payload: payload
  }
};

const items = $input.all();
const context = $('Prepare Sync Context').first().json.context;
const processingTime = Date.now() - context.start_time;

const results = items.map(item => {
  // Check for API errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'OpenAI API error',
          status: 'API_ERROR'
        },
        meta: {
          provider: 'openai',
          execution_mode: context.execution_mode,
          processing_time_ms: processingTime
        }
      }
    };
  }

  try {
    const content = item.json.choices?.[0]?.message?.content || '{}';
    const parsed = JSON.parse(content);

    // Calculate some statistics
    const syllabus = parsed.syllabus || parsed;
    const stats = {
      total_modules: syllabus.modules?.length || 0,
      total_lessons: syllabus.modules?.reduce((sum, m) => sum + (m.lessons?.length || 0), 0) || 0,
      total_hours: syllabus.duration?.total_hours || syllabus.modules?.reduce((sum, m) => sum + (m.duration_hours || 0), 0) || 0
    };

    return {
      json: {
        success: true,
        data: {
          ...parsed,
          statistics: stats
        },
        meta: {
          provider: 'openai',
          model: item.json.model || context.model,
          execution_mode: context.execution_mode,
          tokens_used: item.json.usage?.total_tokens || 0,
          processing_time_ms: processingTime
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Failed to parse syllabus response: ' + e.message,
          status: 'PARSE_ERROR'
        },
        meta: {
          provider: 'openai',
          execution_mode: context.execution_mode,
          processing_time_ms: processingTime
        }
      }
    };
  }
});

return results;
